CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,role VARCHAR(10) NOT NULL CHECK(role IN ('USER','ADMIN')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP WITH TIME ZONE NOT NULL,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE user_lock(id INTEGER PRIMARY KEY);
INSERT INTO user_lock VALUES(1);
CREATE TABLE bookings(id UUID PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),room_id BIGINT,hotel_id BIGINT,start_date DATE NOT NULL,end_date DATE NOT NULL,status VARCHAR(12) NOT NULL CHECK(status IN ('PENDING','CONFIRMED','CANCELLED')),created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,current_operation UUID,pending_operation UUID,version BIGINT NOT NULL DEFAULT 0,CHECK(start_date<end_date));
CREATE INDEX idx_bookings_history ON bookings(user_id,created_at,id);
CREATE TABLE booking_operations(id UUID PRIMARY KEY,booking_id UUID NOT NULL REFERENCES bookings(id),user_id BIGINT NOT NULL REFERENCES users(id),request_id UUID NOT NULL,fingerprint VARCHAR(64) NOT NULL,kind VARCHAR(10) NOT NULL,state VARCHAR(12) NOT NULL,action VARCHAR(32) NOT NULL,room_id BIGINT,hotel_id BIGINT,auto_select BOOLEAN NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,previous_operation UUID,created_at TIMESTAMP WITH TIME ZONE NOT NULL,deadline TIMESTAMP WITH TIME ZONE NOT NULL,next_attempt TIMESTAMP WITH TIME ZONE NOT NULL,lock_until TIMESTAMP WITH TIME ZONE,attempts INTEGER NOT NULL DEFAULT 0,error_status INTEGER,error_code VARCHAR(80),error_message VARCHAR(500),trace_id VARCHAR(32),version BIGINT NOT NULL DEFAULT 0,UNIQUE(user_id,request_id));
CREATE INDEX idx_operations_due ON booking_operations(action,next_attempt,lock_until);
